import{_ as i,l as s,o as e,c as l,v as r,p as d,x as t,d as n,i as p,S as D}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"SPF / DKIM / DMARC","description":"","frontmatter":{"title":"SPF / DKIM / DMARC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/spf-dkim-dmarc.md","filePath":"cs/spf-dkim-dmarc.md","lastUpdated":1789023840000}'),c={name:"cs/spf-dkim-dmarc.md"};function S(h,a,P,m,M,I){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="spf-dkim-dmarc" tabindex="-1">SPF / DKIM / DMARC <a class="header-anchor" href="#spf-dkim-dmarc" aria-label="Permalink to &quot;SPF / DKIM / DMARC&quot;">​</a></h1><div class="epigraph"><p>SPF 授权哪些 IP 能用你的域发信，DKIM 签报头与正文，DMARC 告诉接收方失败时拒还是隔离，并要报告。</p><footer>—— 据 RFC 7208 SPF；RFC 6376 DKIM；RFC 7489 DMARC 整理</footer></div><p><a href="/cs/smtp-imap">SMTP</a> 默认信 MAIL FROM。<a href="/cs/dns">DNS</a> 能放策略记录。<a href="/cs/smtp-imap">上一课</a> 留下伪造。缺口是<strong>域认证三件套</strong>。本课不把 SSH 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>任何人可对 25 说 <code>MAIL FROM: you@bank</code>。SPF：TXT 列合法发送主机，收信方查连接 IP。转发会破 SPF。DKIM：私钥签，公钥在 DNS，转发后仍可验（除非改体）。DMARC：对齐标识，政策 p=reject/quarantine，rua 报告。与 DNSSEC：公钥 TXT 最好也被签。与 RPKI 同构：用 DNS/PKI 钉源。</p><p>不要把三件套写成端到端加密。</p><p><span class="marginnote">RFC 7489。对齐 relaxed/strict。本课不写垃圾分类器特征。</span></p><h3 id="钉域不是加密邮件" tabindex="-1">钉域不是加密邮件 <a class="header-anchor" href="#钉域不是加密邮件" aria-label="Permalink to &quot;钉域不是加密邮件&quot;">​</a></h3><p>SPF 授权 IP，转发会破；DKIM 签体；DMARC 给政策。与 RPKI 同属源认证。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：发出 → DKIM 签 → 收：SPF+DKIM → DMARC 决策。对照 Cookie：都是身份关联，一层邮件域，一层 Web。</p>',11)),(e(),d(D,null,{default:t(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPF%5B%22SPF%20%E6%8E%88%E6%9D%83%20IP%22%5D%20--%3E%20DEC%5B%22DMARC%20%E5%AF%B9%E9%BD%90%22%5D%0A%20%20DKIM%5B%22DKIM%20%E7%AD%BE%E5%90%8D%22%5D%20--%3E%20DEC%0A%20%20DEC%20--%3E%20POL%5B%22none%2Fquarantine%2Freject%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>GeoDNS 不要把 MX 指到未授权 IP。转发列表要 SRS 或 ARC（点名）。TTL 太长使密钥轮换慢。DoH 不改这些 TXT 的语义。</p><p>失败报告帮助发现劫持，也会泄露邮箱元数据，运营权衡。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 BIMI 的全部。SSH 协议是下一课。后课默认：邮件域认证靠 SPF+DKIM+DMARC，不提供机密。</p><p>只开 SPF 不开 DKIM，转发场景脆弱。</p><p>上一课留下的缺口在本课收口；「SPF / DKIM / DMARC」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/ssh-protocol">SSH 协议</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SPF 钉 IP，DKIM 钉内容，DMARC 钉政策。</li><li>转发是 SPF 的经典裂缝。</li><li>与 DNSSEC/RPKI 同属源认证。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 7208；RFC 6376；RFC 7489。</li></ul>',10))])}const f=i(c,[["render",S]]);export{_ as __pageData,f as default};
